\cite[Theorem 3.3]{CCCGW18}\label{Thm:Ecomputability} 
    Let $F \in S_d,$ and $\mathbb{X}\in \mathbb{P}^n$ be an apolar set of $F.$ Let $I$ be an ideal in $T$ generated in degree $e >0,$  and $t \in I_e$. If $t$ is a non-zerodivisor in $T/(I(\mathbb{X})\colon I)$, then for $s >>0,$ we have
    \[ |\mathbb{X}| \geq \frac{1}{e}\sum_{i=0}^s\operatorname{HF}(T/I(\mathbb{X})\colon I +(t), i) \geq \frac{1}{e} \sum_{i=0}^s\operatorname{HF}(T/F^{\perp}\colon I +(t), i).\]

\label{Lemma:ColonRegularSequence}
    Let $h, f_2, \ldots, f_n$ be a regular sequence 
    of homogeneous polynomials in $T$, and 
    $J=(f_2, \ldots, f_n)$. For any homogeneous polynomial $a\in T$ we have
    \begin{align*}
        (J+ (ha)) :(h)= (J:(h)) +(a).
    \end{align*}

\label{Thm:MainRank}
    Let $F \in T$ be such that $F^{\perp}=(X_0^{a_0}+G, \, X_1^{a_1}, \, X_2^{a_2}, \, \ldots, \, X_n^{a_n})$ where $G$ is a form of degree $a_0$ with $ \deg_{X_0} G <a_0$ and $2 \leq a_1 \leq a_2 \leq \cdots \leq a_n.$ Let $\lambda = \min\{a_0, a_1\}$.
    Then
    \[\operatorname{Rk} F =   \begin{dcases}
                    {\frac{1}{\lambda}{\displaystyle\prod_{j=0}^n a_j}} & \text{ if } (X_0^{a_0}+G) \mbox{ has a multiple factor. } \\
                    & \\
                     {a_0{\displaystyle\prod_{j=2}^n a_j}} & \mbox{if } (X_0^{a_0}+G) \mbox{ does not have a multiple factor. }
                \end{dcases}\]

\label{Thm:Binary}
    Let $F=x_0^{a_0}x_1^{a_1}(x_0^{b_0}-x_1^{b_0})$ be a binary binomial with the notation as in Theorem \ref{Thm:Shibata}. Then we have the following:
    \begin{center}
        \begin{tabular}{|c|c|c|}
        \hline
           $v<w$  & $a_1+1 < a_0+b_0+1$ and $a_1+1 -v b_0 \geq 2$ & $\operatorname{Rk} F = a_0+b_0+1 $\\
           \cline{2-3}
             & Otherwise & $\operatorname{Rk} F = a_1+1.$ \\
             \hline
             $v=w$ & $vb_0 \geq   a_0+a_1+2-(v-1)b_0$, $a_1+1-(v-1)b_0 \leq 1$ & $\operatorname{Rk} F = a_0+a_1+2-(v-1)b_0$ \\
             \cline{2-3}
             & \textrm{Otherwise} & $\operatorname{Rk} F = vb_0.$ \\
             \hline
        \end{tabular}
    \end{center}

Let $F =F_1F_2$  where $F_1 \in \mathbb{C}[x_0, x_1]_d$, and $F_2=x_2^{a_2}\cdots x_n^{a_n}$ such that $n \geq 2$, and $a_2 \leq \cdots \leq a_n$ be integers. Then
    \begin{align}\label{EQ:rkFormula}
        \operatorname{Rk} F = (\operatorname{Rk} F_1)\cdot \max\{a_2+1, \deg F_1+2-\operatorname{Rk} F_1\} \cdot\left(\prod_{i=3}^n (a_i+1)\right).
    \end{align}

By Theorem \ref{Thm:BinomialAnnihilator} we have 
   \begin{align*}
       F^{\perp} = (X_0^{a_0+1}+G, X_1^{a_1+b_1+1}, \ldots , X_k^{a_k+b_k+1}, X_{k+1}^{a_{k+1}+1}, \ldots, X_n^{a_n+1}) 
   \end{align*}
  where $G = \sum_{j=1}^m (X_1^{b_1}\cdots X_k^{b_k})^{j} X_0^{a_0+1 - jb_0}$ with 
$m = \min \{\lfloor {\frac{a_i}{b_i}} \rfloor \mid 1 \leq i \leq k\}$. Hence $F^{\perp}$ is a quasi-monomial complete intersection.
We {\it claim} that $G$ is not square-free. That is, we prove that $a_0+1 -mb_0 \geq 2.$ 
    On the contrary, assume that $a_0+1 - mb_0 \leq 1.$ This means
    \begin{equation}\label{EQ:qLeqm}
        q = \lfloor \dfrac{a_0+1}{b_0}\rfloor \leq \lfloor \frac{mb_0+1}{b_0}\rfloor \leq \lfloor m +\frac{1}{b_0} \rfloor = m.
    \end{equation}
    The last equality follows from the fact that $b_0 = \sum_{i=1}^k b_i \geq k \geq 2.$ 
    Moreover, by the definition of $m$ we have $m b_j \leq a_j$ for all $1 \leq j \leq k.$
    By hypothesis there exists $i$ such that $a_i < q b_i$ for some $1 \leq i \leq k.$ 
Therefore, for the same $i$, we have $mb_i \leq a_i <qb_i.$ Since $b_i >0$ we get
    \begin{equation}\label{EQ:mLessthanq}
        m <q.
    \end{equation}
    Hence, by Equations \eqref{EQ:qLeqm} and \eqref{EQ:mLessthanq} we have a contradiction. Therefore, we can write $G = X_0^{a_0+1-mb_0} g$ for some $g\in T.$ Thus $X_0^{a_0+1}+G$ is not square-free. Hence, by Corollary \ref{Thm:MainRank}, we obtain the result.
